15	// tested without a graph plugin installed, and so a missing plugin degrades the
16	// run to text evidence instead of failing it.
17	type GraphClient interface {
18		// Def looks up what a name IS: declaration, file, line.
19		Def(ctx context.Context, symbol string) (*GraphDef, error)
20		// Search finds code for a plain-language task description.
21		Search(ctx context.Context, query string, topK int) (*GraphSearch, error)
22		// Impact reports the blast radius of a symbol — who calls it, what it calls.
