112	// CLIGraphClient runs the real `entire graph` plugin.
113	type CLIGraphClient struct {
114		// Bin is the entire binary to invoke; empty means this running executable.
115		Bin string
116		// Dir is the repository to query.
117		Dir string
118		// Timeout bounds a single query. A cold graph index build on this repo takes
119		// ~48s, so the default must be generous, but an audit must never hang.
120		Timeout time.Duration
121		// LastCommand records the most recent command line, so the report can cite
122		// exactly what a reader should re-run.
123		LastCommand string
124	}
