126	func (g *CLIGraphClient) timeout() time.Duration {
127		if g.Timeout > 0 {
128			return g.Timeout
129		}
130		return 90 * time.Second
131	}
132	
133	func (g *CLIGraphClient) run(ctx context.Context, args ...string) ([]byte, string, error) {
134		bin := g.Bin
135		if bin == "" {
136			var err error
137			if bin, err = os.Executable(); err != nil {
138				return nil, "", fmt.Errorf("locate entire binary: %w", err)
139			}
140		}
141		line := "entire " + strings.Join(args, " ")
142		g.LastCommand = line
143	
144		ctx, cancel := context.WithTimeout(ctx, g.timeout())
145		defer cancel()
146	
147		cmd := exec.CommandContext(ctx, bin, args...)
148		cmd.Dir = g.Dir
149		var stdout, stderr bytes.Buffer
150		cmd.Stdout = &stdout
151		cmd.Stderr = &stderr
152		err := cmd.Run()
153		out := bytes.TrimSpace(stdout.Bytes())
154		if err != nil {
155			return nil, line, fmt.Errorf("%s: %w: %s", line, err, strings.TrimSpace(stderr.String()))
156		}
157		// Without the graph plugin installed, `entire graph ...` prints the root
158		// help text and exits 0. Detect that rather than reporting an empty result,
159		// which would look like "the symbol does not exist" — exactly the kind of
160		// false negative this whole feature exists to prevent.
161		if len(out) == 0 || out[0] != '{' {
162			return nil, line, fmt.Errorf("%s: graph plugin not available (no JSON returned); run `entire plugin install graph`", line)
163		}
164		return out, line, nil
165	}
166	
167	// Available implements [GraphClient].
168	func (g *CLIGraphClient) Available(ctx context.Context) bool {
169		bin := g.Bin
170		if bin == "" {
171			var err error
172			if bin, err = os.Executable(); err != nil {
173				return false
174			}
175		}
176		ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
177		defer cancel()
178		cmd := exec.CommandContext(ctx, bin, "graph", "version")
179		cmd.Dir = g.Dir
180		out, err := cmd.Output()
181		if err != nil {
182			return false
183		}
184		// `graph version` prints a bare version like "v0.4.0" when installed, and the
185		// root help listing when not.
186		return strings.HasPrefix(strings.TrimSpace(string(out)), "v")
187	}
