232	// completenessFromDiagnostics maps the graph's own warnings onto the audit's
233	// completeness scale. A partial parse failure means the graph did not see the
234	// whole tree, so any absence it reports is not authoritative.
235	func completenessFromDiagnostics(warnings, partials []GraphDiagnostic) Completeness {
236		for _, p := range partials {
237			if p.Severity == "error" {
238				return CompletenessPartial
239			}
240		}
241		if len(partials) > 0 {
242			return CompletenessPartial
243		}
244		for _, w := range warnings {
245			// A worktree snapshot is a complete read of the tree we were asked about.
246			if w.Code == "W_WORKTREE_SNAPSHOT" {
247				continue
248			}
249			if w.Severity == "error" || w.Severity == "warning" {
250				return CompletenessPartial
251			}
252		}
253		return CompletenessComplete
254	}
